void DataRecorder::onImageFrame()
{
    if (!m_image.saving || !m_imageData) return;
    ensureSourceFile(m_image, QStringLiteral("image"), kImageHeader, "图像");
    if (m_image.openFailed) return;
    m_image.buffer.append(buildImageCsvLine().toUtf8());
}
